tool_input.new_string:
/** 整改状态查看态展示：值转对应字典文案，未填显示占位符 */
rectifyStateText() {
  const val = this.form.rectifyState
  if (val === null || val === undefined || String(val).trim() === '') return '—'
  const hit = RECTIFY_OPTIONS.find((opt) => opt.dictValue === String(val))
  return hit ? hit.dictLabel : val
},
/** 整改与复盘：查看态用 DetailTemplate 展示的字段定义（测量措施整行，其余三项各占 1/3） */
rectifyDetailItems() {
  const L3 = { xs: 24, sm: 24, md: 8, lg: 8, xl: 8 }
  return [
    { label: '整改措施', value: this.form.rectifyMeasure, type: 'textarea', layout: { xs: 24, sm: 24, md: 24, lg: 24, xl: 24 } },
    { label: '整改期限', value: this.form.rectifyDeadline, type: 'text', layout: L3 },
    { label: '整改状态', value: this.rectifyStateText, type: 'text', layout: L3 },
    { label: '整改责任人', value: this.form.rectifyUser, type: 'text', layout: L3 }
  ]
},

